        when left(upper({{ code_column }}), 3) between 'T51' and 'T65' then 'T51-T65 Toxic effects of substances chiefly nonmedicinal as to source'
        when left(upper({{ code_column }}), 3) between 'T66' and 'T78' then 'T66-T78 Other and unspecified effects of external causes'
        when left(upper({{ code_column }}), 3) between 'T79' and 'T79' then 'T79-T79 Certain early complications of trauma'
        when left(upper({{ code_column }}), 3) between 'T80' and 'T88' then 'T80-T88 Complications of surgical and medical care, not elsewhere classified'
        when left(upper({{ code_column }}), 3) between 'T90' and 'T98' then 'T90-T98 Sequelae of injuries, of poisoning and of other consequences of external causes'
        when left(upper({{ code_column }}), 3) between 'V01' and 'X59' then 'V01-X59 Accidents'
        when left(upper({{ code_column }}), 3) between 'X60' and 'X84' then 'X60-X84 Intentional self-harm'
        when left(upper({{ code_column }}), 3) between 'X85' and 'Y09' then 'X85-Y09 Assault'
        when left(upper({{ code_column }}), 3) between 'Y10' and 'Y34' then 'Y10-Y34 Event of undetermined intent'
        when left(upper({{ code_column }}), 3) between 'Y35' and 'Y36' then 'Y35-Y36 Legal intervention and operations of war'
        when left(upper({{ code_column }}), 3) between 'Y40' and 'Y84' then 'Y40-Y84 Complications of medical and surgical care'
        when left(upper({{ code_column }}), 3) between 'Y85' and 'Y89' then 'Y85-Y89 Sequelae of external causes of morbidity and mortality'
        when left(upper({{ code_column }}), 3) between 'Y90' and 'Y98' then 'Y90-Y98 Supplementary factors related to causes of morbidity and mortality classified elsewhere'
        when left(upper({{ code_column }}), 3) between 'Z00' and 'Z13' then 'Z00-Z13 Persons encountering health services for examination and investigation'
        when left(upper({{ code_column }}), 3) between 'Z20' and 'Z29' then 'Z20-Z29 Persons with potential health hazards related to communicable diseases'
        when left(upper({{ code_column }}), 3) between 'Z30' and 'Z39' then 'Z30-Z39 Persons encountering health services in circumstances related to reproduction'
        when left(upper({{ code_column }}), 3) between 'Z40' and 'Z54' then 'Z40-Z54 Persons encountering health services for specific procedures and health care'
        when left(upper({{ code_column }}), 3) between 'Z55' and 'Z65' then 'Z55-Z65 Persons with potential health hazards related to socioeconomic and psychosocial circumstances'
        when left(upper({{ code_column }}), 3) between 'Z70' and 'Z76' then 'Z70-Z76 Persons encountering health services in other circumstances'
        when left(upper({{ code_column }}), 3) between 'Z80' and 'Z99' then 'Z80-Z99 Persons with potential health hazards related to family and personal history and certain conditions influencing health status'
        when left(upper({{ code_column }}), 3) between 'U00' and 'U49' then 'U00-U49 Provisional assignment of new diseases of uncertain etiology or emergency use'
        when left(upper({{ code_column }}), 3) between 'U82' and 'U85' then 'U82-U85 Resistance to antimicrobial and antineoplastic drugs'
        else 'Unclassified'
    end
{% endmacro %}
